const out = $input.first().json || {};

if (out.broker !== 'supabase') {
  throw new Error(`GTM 08 expected supabase broker, got ${out.broker}`);
}
if (out.broker_version !== 'SB-BROKER-V3.0.0') {
  throw new Error(`GTM 08 expected SB-BROKER-V3.0.0, got ${out.broker_version}`);
}
if (out.rpc_name !== 'gtm_outreach_dispatch_plan_v1') {
  throw new Error(`GTM 08 unexpected RPC echo: ${out.rpc_name}`);
}

const rows = Array.isArray(out.response) ? out.response : [];

if (rows.length !== 7) {
  throw new Error(`GTM 08 expected 7 dispatch rows, got ${rows.length}`);
}

const sendReady = rows.filter(x => x.send_ready === true).length;
const dispatchable = rows.filter(x => x.dispatch_action === 'dispatchable').length;
const blockedByGate = rows.filter(x => x.dispatch_action === 'blocked_by_send_gate').length;
const providerLive = rows.filter(x => x.provider_live_enabled === true).length;

if (sendReady !== 0) throw new Error(`GTM 08 expected 0 send-ready rows, got ${sendReady}`);
if (dispatchable !== 0) throw new Error(`GTM 08 expected 0 dispatchable rows, got ${dispatchable}`);
if (blockedByGate !== 7) throw new Error(`GTM 08 expected all 7 blocked_by_send_gate, got ${blockedByGate}`);
if (providerLive !== 0) throw new Error(`GTM 08 expected SMTP2GO provider disabled for all rows`);

const first = rows[0];

if (!first?.provider_envelope || typeof first.provider_envelope !== 'object') {
  throw new Error('GTM 08 first dispatch row missing provider_envelope');
}
if (!first.task_key || !first.content_hash) {
  throw new Error('GTM 08 first dispatch row missing task_key/content_hash');
}

const env = first.provider_envelope;
const recipients = Array.isArray(env.to) ? env.to : [];

if (recipients.length !== 1) {
  throw new Error('GTM 08 expected exactly one recipient in dry-run envelope');
}
if (!env.subject || !env.text_body) {
  throw new Error('GTM 08 dry-run envelope missing subject/body');
}

return [{
  json: {
    dispatch_plan_passed: true,
    dispatch_rows: rows.length,
    send_ready_rows: sendReady,
    dispatchable_rows: dispatchable,
    blocked_by_send_gate_rows: blockedByGate,
    provider_live_enabled_rows: providerLive,
    sample_full_name: first.full_name,
    sample_task_key: first.task_key,
    sample_content_hash: first.content_hash,
    sample_to: recipients,
    sample_subject: env.subject,
    sample_text_body: env.text_body
  }
}];

const dispatch = $('Validate Provider Dispatch Plan').first().json;
const smtp = $input.first().json || {};

if (smtp.broker !== 'smtp2go') {
  throw new Error(`GTM 08 expected smtp2go broker, got ${smtp.broker}`);
}
if (smtp.broker_version !== 'SMTP2GO-BROKER-V1.0.0') {
  throw new Error(`GTM 08 expected SMTP2GO-BROKER-V1.0.0, got ${smtp.broker_version}`);
}
if (smtp.operation !== 'validate_payload') {
  throw new Error(`GTM 08 unexpected SMTP2GO operation: ${smtp.operation}`);
}
if (smtp.live_send_enabled !== false) {
  throw new Error('GTM 08 dry-run requires live_send_enabled=false');
}
if (smtp.payload_valid !== true) {
  throw new Error('GTM 08 SMTP2GO payload validation did not pass');
}

const payload = smtp.provider_payload || {};
const to = Array.isArray(payload.to) ? payload.to : [];

if (to.length !== 1) {
  throw new Error('GTM 08 normalized SMTP2GO payload recipient count mismatch');
}
if (!payload.subject || !payload.text_body) {
  throw new Error('GTM 08 normalized SMTP2GO payload missing subject/body');
}

return [{
  json: {
    gtm08_dry_run_completed: true,
    supabase_broker_v3_passed: dispatch.dispatch_plan_passed === true,
    smtp2go_broker_passed: true,
    supabase_workflow_id: 'SUPABASE_BROKER_V3_WORKFLOW_ID',
    smtp2go_workflow_id: 'SMTP2GO_BROKER_WORKFLOW_ID',
    dispatch_rows: dispatch.dispatch_rows,
    send_ready_rows: dispatch.send_ready_rows,
    dispatchable_rows: dispatch.dispatchable_rows,
    blocked_by_send_gate_rows: dispatch.blocked_by_send_gate_rows,
    provider_live_enabled: smtp.live_send_enabled,
    provider_http_call_performed: false,
    sample_full_name: dispatch.sample_full_name,
    sample_recipient: to[0],
    sample_subject: payload.subject,
    sample_task_key: dispatch.sample_task_key,
    sample_content_hash: dispatch.sample_content_hash,
    credentials_required_in_parent: false,
    gtm08_dry_run_all_checks_pass:
      dispatch.dispatch_plan_passed === true &&
      dispatch.dispatch_rows === 7 &&
      dispatch.send_ready_rows === 0 &&
      dispatch.dispatchable_rows === 0 &&
      dispatch.blocked_by_send_gate_rows === 7 &&
      smtp.live_send_enabled === false &&
      smtp.payload_valid === true,
    next_stage:
      'Install delivery/reply lifecycle foundation and reporting/QA while live sending remains disabled.'
  }
}];
